class Solution {
public:
    string decodeString(string s) {
        vector<pair<string, int>> st;
        string currStr = "";
        int currNum = 0;
        for (char c : s) {
            if (isdigit(c)) {
                currNum = currNum * 10 + (c - '0');
            } else if (c == '[') {
                st.push_back({currStr, currNum});
                currStr = "";
                currNum = 0;
            } else if (c == ']') {
                auto [prevStr, k] = st.back(); st.pop_back();
                string repeated = "";
                for (int i = 0; i < k; i++) repeated += currStr;
                currStr = prevStr + repeated;
            } else {
                currStr += c;
            }
        }
        return currStr;
    }
};

class Solution {
    public String decodeString(String s) {
        java.util.ArrayDeque<String> strSt = new java.util.ArrayDeque<>();
        java.util.ArrayDeque<Integer> numSt = new java.util.ArrayDeque<>();
        StringBuilder currStr = new StringBuilder();
        int currNum = 0;
        for (char c : s.toCharArray()) {
            if (Character.isDigit(c)) {
                currNum = currNum * 10 + (c - '0');
            } else if (c == '[') {
                strSt.push(currStr.toString());
                numSt.push(currNum);
                currStr = new StringBuilder();
                currNum = 0;
            } else if (c == ']') {
                int k = numSt.pop();
                String prev = strSt.pop();
                StringBuilder sb = new StringBuilder(prev);
                for (int i = 0; i < k; i++) sb.append(currStr);
                currStr = sb;
            } else {
                currStr.append(c);
            }
        }
        return currStr.toString();
    }
}

var decodeString = function(s) {
    const st = [];
    let currStr = '';
    let currNum = 0;
    for (const c of s) {
        if (c >= '0' && c <= '9') {
            currNum = currNum * 10 + Number(c);
        } else if (c === '[') {
            st.push([currStr, currNum]);
            currStr = '';
            currNum = 0;
        } else if (c === ']') {
            const [prevStr, k] = st.pop();
            currStr = prevStr + currStr.repeat(k);
        } else {
            currStr += c;
        }
    }
    return currStr;
};
